package main

import (
	"crypto/subtle"
	"encoding/base64"
	"strconv"
	"strings"
)

// Accounts 允许登录的账号：键是用户名，值是明文密码。
type Accounts map[string]string

// CredentialPrefix 是 Authorization 头里 base64 载荷之前的方案名（含一个尾随空格）。
const CredentialPrefix = "Basic "

// DefaultRealm 是 realm 为空串时使用的名称。
const DefaultRealm = "Authorization Required"

// ChallengeHeader 生成 401 响应的 WWW-Authenticate 值：
// realm 为空串时回落到 DefaultRealm，realm 本身按带引号的转义形式输出。
func ChallengeHeader(realm string) string {
	if realm == "" {
		realm = DefaultRealm
	}
	return CredentialPrefix + "realm=" + strconv.Quote(realm)
}

// Authenticate 校验 Authorization 头的值。
// 通过时返回账号表里的用户名与 true；任何一步不成立返回 "" 与 false。
func Authenticate(accounts Accounts, header string) (string, bool) {
	payload, ok := credentialPayload(header)
	if !ok {
		return "", false
	}
	parts := strings.Split(payload, ":")
	if len(parts) != 2 {
		return "", false
	}
	user, password := parts[0], parts[1]
	stored, existed := accounts[user]
	if !existed {
		return "", false
	}
	if subtle.ConstantTimeCompare([]byte(stored), []byte(password)) != 1 {
		return "", false
	}
	return user, true
}

// credentialPayload 取出前缀之后的 base64 载荷并解码。
// 前缀大小写不敏感；载荷是前缀之后剩下的全部字符，且必须是合法的标准 base64。
func credentialPayload(header string) (string, bool) {
	if len(header) <= len(CredentialPrefix) {
		return "", false
	}
	if !strings.EqualFold(header[:len(CredentialPrefix)], CredentialPrefix) {
		return "", false
	}
	raw, err := base64.StdEncoding.DecodeString(header[len(CredentialPrefix):])
	if err != nil {
		return "", false
	}
	return string(raw), true
}

