// Accounts 允许登录的账号：键是用户名，值是明文密码。
type Accounts map[string]string

// CredentialPrefix 是 Authorization 头里 base64 载荷之前的方案名（含一个尾随空格）。
const CredentialPrefix = "Basic "

// DefaultRealm 是 realm 为空串时使用的名称。
const DefaultRealm = "Authorization Required"

// ChallengeHeader 生成 401 响应的 WWW-Authenticate 值：
// realm 为空串时回落到 DefaultRealm，realm 本身按带引号的转义形式输出。
func ChallengeHeader(realm string) string {
	if realm == "" {
		realm = DefaultRealm
	}
	return CredentialPrefix + "realm=" + strconv.Quote(realm)
