// 通过时返回账号表里的用户名与 true；任何一步不成立返回 "" 与 false。
func Authenticate(accounts Accounts, header string) (string, bool) {
	payload, ok := credentialPayload(header)
	if !ok {
		return "", false
	}
	idx := strings.IndexByte(payload, ':')
	if idx < 0 {
		return "", false
	}
	user, password := payload[:idx], payload[idx+1:]
	stored, existed := accounts[user]
	if !existed {
		return "", false
	}
	if subtle.ConstantTimeCompare([]byte(stored), []byte(password)) != 1 {
		return "", false
	}
	return user, true
}

// credentialPayload 取出前缀之后的 base64 载荷并解码。
// 前缀大小写不敏感；载荷是前缀之后剩下的全部字符，且必须是合法的标准 base64。
func credentialPayload(header string) (string, bool) {
	if len(header) <= len(CredentialPrefix) {
		return "", false
	}
	if !strings.EqualFold(header[:len(CredentialPrefix)], CredentialPrefix) {
		return "", false
	}
	raw, err := base64.StdEncoding.DecodeString(header[len(CredentialPrefix):])
	if err != nil {
		return "", false
	}
	return string(raw), true
}

