package main

import (
	"encoding/base64"
	"fmt"
	"os"
)

var passCount, failCount int

func record(name string, ok bool, detail string) {
	if ok {
		passCount++
		return
	}
	failCount++
	fmt.Fprintf(os.Stderr, "FAIL %s: %s\n", name, detail)
}

func b64(s string) string {
	return base64.StdEncoding.EncodeToString([]byte(s))
}

func hdr(cred string) string {
	return "Basic " + b64(cred)
}

func checkAuth(name string, accounts Accounts, header string, wantUser string, wantFound bool) {
	gotUser, gotFound := Authenticate(accounts, header)
	if gotUser == wantUser && gotFound == wantFound {
		record(name, true, "")
		return
	}
	record(name, false, fmt.Sprintf("Authenticate 返回 (%q, %v)，期望 (%q, %v)", gotUser, gotFound, wantUser, wantFound))
}

func checkChallenge(name, realm, want string) {
	got := ChallengeHeader(realm)
	if got == want {
		record(name, true, "")
		return
	}
	record(name, false, fmt.Sprintf("ChallengeHeader(%q) 返回 %q，期望 %q", realm, got, want))
}

func main() {
	accounts := Accounts{"admin": "password", "foo": "bar"}

	checkAuth("普通账号通过", accounts, hdr("admin:password"), "admin", true)
	checkAuth("多账号里命中正确用户", accounts, hdr("foo:bar"), "foo", true)
	checkAuth("密码不符拒绝", accounts, hdr("admin:password1"), "", false)
	checkAuth("未知用户拒绝", accounts, hdr("guest:password"), "", false)
	checkAuth("空用户名拒绝", accounts, hdr(":password"), "", false)
	checkAuth("载荷没有冒号拒绝", accounts, hdr("admin"), "", false)
	checkAuth("空密码账号通过", Accounts{"guest": ""}, hdr("guest:"), "guest", true)
	checkAuth("密码含冒号通过", Accounts{"root": "pa:ss:word"}, hdr("root:pa:ss:word"), "root", true)
	checkAuth("密码含冒号但结尾不同仍拒绝", Accounts{"root": "pa:ss:word"}, hdr("root:pa:ss"), "", false)
	checkAuth("密码以冒号结尾通过", Accounts{"svc": "tok:"}, hdr("svc:tok:"), "svc", true)
	checkAuth("用户名区分大小写", Accounts{"Admin": "pw"}, hdr("admin:pw"), "", false)
	checkAuth("空请求头拒绝", accounts, "", "", false)
	checkAuth("只有前缀拒绝", accounts, "Basic ", "", false)
	checkAuth("其它 scheme 拒绝", accounts, "Bearer "+b64("admin:password"), "", false)
	checkAuth("scheme 大小写不敏感", accounts, "basic "+b64("admin:password"), "admin", true)
	checkAuth("载荷非法 base64 拒绝", accounts, "Basic ###", "", false)
	checkAuth("载荷缺 padding 拒绝", accounts, "Basic YWRtaW46cGFzc3dvcmQ", "", false)
	checkAuth("nil 账号表不 panic", nil, hdr("admin:password"), "", false)

	checkChallenge("默认 realm", "", `Basic realm="Authorization Required"`)
	checkChallenge("自定义 realm", "proxy", `Basic realm="proxy"`)
	checkChallenge("realm 里的引号转义", `My Custom "Realm"`, `Basic realm="My Custom \"Realm\""`)

	fmt.Printf("TESTS %d %d\n", passCount, failCount)
	if failCount > 0 {
		os.Exit(1)
	}
}
